# ---- ШІСТЬ ВИДІВ (RISHENNYA, розд. 18; виконано 27.09.2026) ----
# «Середовище і майно громади» зникає. Правка стоїть окремим блоком поверх
# переліку вище, а не в ньому: перелік збирається автоматично з категорій
# ЄДРСР, і ручні зміни всередині загубилися б при першій перебудові (про те
# саме — mech.py). Склад — строго за таблицею розд. 18.
# Статті «Середовища», яких у таблиці немає (150, 151, 152-1, 153, 175, 191
# КУпАП, 270-1 ККУ), не викидаються з переліку — інакше step0 перестав би
# качати їхні документи, — а позначаються «поза видами»: карта й звіти їх
# не рахують, збірка друкує, скільки таких подій відсіяно. 27.09 серед подій
# карти їх 0.
_DO_GP = ('ст.152 КУпАП', 'ст.154 КУпАП', 'ст.192 КУпАП', 'ст.270 КК', 'ст.297 КК', 'ст.299 КК')
_DO_MAI = ('ст.197-1 КК',)
POZA = 'ПОЗА'
for _code, (_th, _lab) in list(CODE.items()):
    _art = _lab.split(' · ')[0]
    _new = 'ГП' if _art in _DO_GP else 'МАЙ' if _art in _DO_MAI else (POZA if _th == 'СЕР' else None)
    if not _new or _new == _th: continue
    CODE[_code] = (_new, _lab)
    # Механізм переходить разом зі статтею: «СЕР_зброя» -> «ГП_зброя». Сусіди по
    # колишньому механізму, що лишилися поза видами (191 при 192), дістають
    # свій «ПОЗА_…», тож механізми видів не змішуються з тим, що поза ними.
    _sim = SIMGROUP.get(_code)
    if _sim:
        _nsim = _new + '_' + _sim.split('_', 1)[1]
        SIMGROUP[_code] = _nsim
        GROUPNAME.setdefault(_nsim, GROUPNAME.get(_sim, _sim.split('_', 1)[1]))
THEMES.pop('СЕР', None)
THEMES[POZA] = 'поза видами'
ORDER.remove('СЕР')


