# ---- ДОМАШНЄ НАСИЛЬСТВО — У «НАСИЛЬСТВІ» (RISHENNYA 35.8) ----
# Окремий вид «ДОМ» існував, щоб ці справи не йшли на карту. Андрій 06.10:
# на карті, як усі, — точкою, з фабулою, кольором «Насильства» (34.3).
for _c, (_th, _lab) in list(CODE.items()):
    if _th == 'ДОМ':
        CODE[_c] = ('НАС', _lab)
        SIMGROUP[_c] = 'НАС_домашнє'
THEMES.pop('ДОМ', None)
ORDER.remove('ДОМ')

# ---- ДТП І ПОРУШЕННЯ НА ДОРОЗІ — ДВА ВИДИ (RISHENNYA 34.3) ----
# «ДТП» — подія з наслідком (майно, потерпілі, втеча з місця); «Порушення на
# дорозі» — решта дорожніх протоколів, здебільшого проактивних. Ключ «ДОР»
# лишається за порушеннями, щоб не міняти назв механізмів (ДОР_ДТП тощо) —
# вони живуть у моделі, звітах і risk.json. Механізм ДТП знає свій вид через
# mech.simtheme, а не через префікс.
_DTP_ART = ('ст.124 КУпАП', 'ст.122-4 КУпАП', 'ст.286 КК', 'ст.415 КК')
for _c, (_th, _lab) in list(CODE.items()):
    if _th == 'ДОР' and _lab.split(' · ')[0] in _DTP_ART:
        CODE[_c] = ('ДТП', _lab)
THEMES['ДТП'] = 'ДТП'
THEMES['ДОР'] = 'Порушення на дорозі'
ORDER.insert(ORDER.index('ДОР'), 'ДТП')
